def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [a for a, b in history]
    op = [b for a, b in history]

    opp_c = sum(1 for x in op if x == 'C')
    opp_d = n - opp_c
    opp_rate = opp_c / n
    my_d = sum(1 for x in me if x == 'D')

    recent_len = min(12, n)
    recent_op = op[-recent_len:]
    recent_opp_c = sum(1 for x in recent_op if x == 'C')
    recent_rate = recent_opp_c / recent_len

    run_d = 0
    for x in reversed(op):
        if x == 'D':
            run_d += 1
        else:
            break

    run_c = 0
    for x in reversed(op):
        if x == 'C':
            run_c += 1
        else:
            break

    last_my = me[-1]
    last_op = op[-1]

    start = max(1, n - 20)
    tC = 0
    tD = 0
    cC = 0
    cD = 0

    for i in range(start, n):
        prev = me[i - 1]
        cur = op[i]
        if prev == 'C':
            tC += 1
            if cur == 'C':
                cC += 1
        else:
            tD += 1
            if cur == 'C':
                cD += 1

    if tC >= 3:
        pC = cC / tC
    else:
        pC = opp_rate

    if tD == 0:
        if opp_rate >= 0.62:
            pD = 0.0
        else:
            pD = pC
    else:
        pD = cD / tD

    punish = pC - pD

    if opp_rate <= 0.22 and recent_rate <= 0.32:
        return 'D'

    if run_d >= 8 and recent_rate <= 0.42:
        return 'D'

    if last_my == 'D' and last_op == 'D':
        if pD >= 0.6 and punish <= 0.15 and recent_rate < 0.75:
            return 'D'
        if opp_rate > 0.63 or recent_rate > 0.65 or (pC > 0.68 and punish > 0.25):
            return 'C'
        return 'D'

    if last_my == 'C' and last_op == 'D':
        if pD >= 0.6 and punish <= 0.15 and recent_rate < 0.75:
            return 'D'
        if opp_rate > 0.63 or recent_rate > 0.63 or (pC >= 0.65 and punish >= 0.25):
            return 'C'
        return 'D'

    if last_my == 'D' and last_op == 'C':
        if pD >= 0.65 and punish <= 0.35:
            return 'D'
        if opp_rate <= 0.3 or recent_rate <= 0.35:
            return 'D'
        if pC >= 0.6 and punish > 0.25:
            return 'C'
        if opp_rate > 0.55 or recent_rate > 0.55:
            return 'C'
        return 'D'

    if pD >= 0.65 and punish <= 0.35:
        return 'D'

    if punish <= 0.15 and pC >= 0.5 and opp_rate >= 0.4:
        return 'D'

    if my_d == 0 and run_c >= 15 and n < 95:
        if opp_d == 0 or (opp_d >= 4 and opp_rate >= 0.55):
            return 'D'

    return 'C'
